import csv
import io
import re


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(max(previous_limit, len(raw_csv)))
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    number = re.compile(
        r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
    )

    def is_number(value):
        return bool(number.fullmatch(value.strip()))

    header_index = 0
    if (
        len(records) >= 3
        and len(records[0]) != 2
        and len(records[1]) == 2
        and not all(is_number(value) for value in records[1])
        and len(records[2]) == 2
        and all(is_number(value) for value in records[2])
    ):
        header_index = 1

    columns = list(records[header_index])
    rows = records[header_index + 1:]
    width = max([len(columns)] + [len(row) for row in rows])

    used = set(columns)
    extra_number = 1
    while len(columns) < width:
        name = "extra_" + str(extra_number)
        extra_number += 1
        if name not in used:
            columns.append(name)
            used.add(name)

    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
